#!/usr/bin/env python3
import json, sys, time, uuid, urllib.request, urllib.error

BASE = "http://10.0.179.145:8188"

def http(method, path, body=None, ctype="application/json", timeout=30):
    url = BASE + path
    data = None
    headers = {}
    if body is not None:
        if isinstance(body, (dict, list)):
            data = json.dumps(body).encode()
            headers["Content-Type"] = ctype
        else:
            data = body if isinstance(body, bytes) else str(body).encode()
            headers["Content-Type"] = ctype
    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, dict(r.headers), r.read()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read()
    except Exception as e:
        return None, {}, str(e).encode()

def submit(prompt, client_id=None):
    if client_id is None:
        client_id = str(uuid.uuid4())[:8]
    body = {"prompt": prompt, "client_id": client_id}
    st, h, b = http("POST", "/api/prompt", body)
    txt = b.decode(errors="replace")
    return st, txt, client_id

def get_history(prompt_id, timeout=60):
    end = time.time() + timeout
    while time.time() < end:
        st, h, b = http("GET", f"/history/{prompt_id}")
        if st == 200:
            return json.loads(b.decode(errors="replace"))
        time.sleep(1.0)
    return {"_timeout": True}

def run(name, prompt, echo=True, wait=60):
    st, txt, cid = submit(prompt)
    if echo:
        print(f"### {name}: POST /api/prompt -> {st}")
        print("    resp:", txt[:500])
    if st != 200:
        return None
    try:
        pid = json.loads(txt).get("prompt_id")
    except Exception:
        pid = None
    if not pid:
        print("    !! no prompt_id")
        return None
    hist = get_history(pid, wait)
    print(f"### {name}: history/{pid}")
    print(json.dumps(hist, indent=1)[:4000])
    print()
    return hist

def node(cls, **inputs):
    return {"class_type": cls, "inputs": inputs}

if __name__ == "__main__":
    pass
